BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DB_FILE = os.path.join(BASE_DIR, "saheemnet.db")

def get_db():
    con = sqlite3.connect(DB_FILE)
    con.row_factory = sqlite3.Row
    return con

def init_db():
    with get_db() as con:
        con.executescript("""
        CREATE TABLE IF NOT EXISTS admins(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );

        CREATE TABLE IF NOT EXISTS customers(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            company TEXT,
            phone TEXT,
            email TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            status TEXT DEFAULT 'نشط',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );

        CREATE TABLE IF NOT EXISTS products(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            annual_price REAL DEFAULT 0,
            status TEXT DEFAULT 'متاح',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );

        CREATE TABLE IF NOT EXISTS orders(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            phone TEXT,
            email TEXT,
            request_type TEXT,
            details TEXT,
            status TEXT DEFAULT 'جديد',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );

        CREATE TABLE IF NOT EXISTS contact_messages(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            phone TEXT,
            email TEXT NOT NULL,
            subject TEXT NOT NULL,
            message TEXT NOT NULL,
            status TEXT DEFAULT 'جديدة',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );

        CREATE TABLE IF NOT EXISTS password_resets(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            customer_id INTEGER NOT NULL,
            token TEXT UNIQUE NOT NULL,
            expires_at TEXT NOT NULL,
            used INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(customer_id) REFERENCES customers(id)
        );

        CREATE TABLE IF NOT EXISTS subscriptions(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            customer_id INTEGER NOT NULL,
            product_id INTEGER NOT NULL,
            license_type TEXT DEFAULT 'سنوي',
            device_count INTEGER DEFAULT 1,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            status TEXT DEFAULT 'نشط',
            license_key TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(customer_id) REFERENCES customers(id),
            FOREIGN KEY(product_id) REFERENCES products(id)
        );
        """)
        try:
            con.execute("""CREATE UNIQUE INDEX IF NOT EXISTS idx_unique_active_subscription
                           ON subscriptions(customer_id, product_id)
                           WHERE status='نشط'""")
        except sqlite3.IntegrityError:
            pass

        # تحديثات قاعدة البيانات للإصدارات الجديدة بدون حذف البيانات السابقة
        sub_cols = {r["name"] for r in con.execute("PRAGMA table_info(subscriptions)").fetchall()}
        if "price" not in sub_cols:
            con.execute("ALTER TABLE subscriptions ADD COLUMN price REAL DEFAULT 0")
        if "payment_status" not in sub_cols:
            con.execute("ALTER TABLE subscriptions ADD COLUMN payment_status TEXT DEFAULT 'غير مدفوع'")

        count = con.execute("SELECT COUNT(*) FROM products").fetchone()[0]
        if count == 0:
            seed = [
                ("نظام حصر الأجهزة وتقنية المعلومات",
                 "إدارة أجهزة الحاسب والطابعات والماسحات ومتابعة الأصول والتقارير.", 0),
                ("نظام بيانات الموظفين",
                 "إدارة بيانات الموظفين والإجازات والمستندات والتقارير.", 0),
                ("نظام خدمات المراجعين",
                 "تسجيل المراجعين والخدمات والتقارير والإحصائيات.", 0),
                ("نظام مخصص",
                 "تصميم وبرمجة نظام حسب احتياج العميل.", 0),
            ]
            con.executemany(
                "INSERT INTO products(name,description,annual_price) VALUES(?,?,?)", seed
            )

def admin_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        if not session.get("admin_id"):
            return redirect(url_for("admin_login"))
        return fn(*args, **kwargs)
    return wrapper

def customer_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        if not session.get("customer_id"):
            return redirect(url_for("login"))
        return fn(*args, **kwargs)
    return wrapper

