@app.route("/reset-password", methods=["GET", "POST"])
def reset_password():
    error = ""
    email_prefill = request.args.get("email", "")
    if request.method == "POST":
        email = request.form.get("email", "").strip().lower(); token = request.form.get("token", "").strip()
        password = request.form.get("password", ""); confirm = request.form.get("confirm", "")
        if len(password) < 8:
            error = '<div class="notice" style="background:#fdecec;color:#a52a2a">كلمة المرور يجب أن تكون 8 أحرف على الأقل.</div>'
        elif password != confirm:
            error = '<div class="notice" style="background:#fdecec;color:#a52a2a">تأكيد كلمة المرور غير مطابق.</div>'
        else:
            with get_db() as con:
                row = con.execute("""SELECT pr.*,c.id customer_id FROM password_resets pr JOIN customers c ON c.id=pr.customer_id WHERE lower(c.email)=? AND pr.token=? AND pr.used=0 ORDER BY pr.id DESC LIMIT 1""", (email,token)).fetchone()
                valid = bool(row and datetime.fromisoformat(row["expires_at"]) >= datetime.now())
                if valid:
                    con.execute("UPDATE customers SET password_hash=? WHERE id=?", (generate_password_hash(password),row["customer_id"]))
                    con.execute("UPDATE password_resets SET used=1 WHERE customer_id=?", (row["customer_id"],))
                    return redirect(url_for("login",reset=1))
            error = '<div class="notice" style="background:#fdecec;color:#a52a2a">رمز الاستعادة غير صحيح أو انتهت صلاحيته.</div>'
    content=f"""<section><div class="container"><div class="section-title"><h2>تعيين كلمة مرور جديدة</h2><p>أدخل رمز الاستعادة ثم اختر كلمة مرور جديدة.</p></div><div class="form-box">{error}<form method="POST"><input name="email" type="email" value="{email_prefill}" placeholder="البريد الإلكتروني" required><br><br><input name="token" inputmode="numeric" maxlength="6" placeholder="رمز الاستعادة - 6 أرقام" required><br><br><input name="password" type="password" minlength="8" placeholder="كلمة المرور الجديدة" required><br><br><input name="confirm" type="password" minlength="8" placeholder="تأكيد كلمة المرور الجديدة" required><br><br><button class="btn btn-green" style="width:100%" type="submit">حفظ كلمة المرور الجديدة</button></form></div></div></section>"""
    return page("تعيين كلمة مرور جديدة",content)


@app.route("/admin/subscriptions/<int:subscription_id>/renew", methods=["POST"])
@admin_required
def admin_renew_subscription(subscription_id):
    from datetime import timedelta
    with get_db() as con:
        sub = con.execute("SELECT * FROM subscriptions WHERE id=?", (subscription_id,)).fetchone()
        if sub:
            today = date.today()
            try:
                old_end = datetime.strptime(sub["end_date"], "%Y-%m-%d").date()
            except Exception:
                old_end = today
            base = old_end if old_end >= today else today
            new_end = base + timedelta(days=365)
            con.execute("UPDATE subscriptions SET end_date=?, status='نشط' WHERE id=?",
                        (new_end.isoformat(), subscription_id))
    return redirect(url_for("admin_subscriptions"))

@app.route("/customer")
@customer_required
def customer_dashboard():
    cid = session["customer_id"]
    today = date.today()

    with get_db() as con:
        customer = con.execute("SELECT * FROM customers WHERE id=?", (cid,)).fetchone()
        subs = con.execute("""
            SELECT s.*, p.name product_name
            FROM subscriptions s
            JOIN products p ON p.id=s.product_id
            WHERE s.customer_id=?
            ORDER BY s.end_date DESC
        """, (cid,)).fetchall()

    active = expiring = expired = 0
    rows = ""
    for s in subs:
        try:
            end = datetime.strptime(s["end_date"], "%Y-%m-%d").date()
            remaining = (end - today).days
        except Exception:
            remaining = None

        stored = s["status"] or "نشط"
        if stored in ("موقوف", "ملغي"):
            display_status = stored
        elif remaining is not None and remaining < 0:
            display_status = "منتهي"
            expired += 1
        elif remaining is not None and remaining <= 30:
            display_status = "قريب الانتهاء"
            expiring += 1
        else:
            display_status = "نشط"
            active += 1

        remaining_text = "—" if remaining is None else ("منتهي" if remaining < 0 else f"{remaining} يوم")
        price = float(s["price"] or 0) if "price" in s.keys() else 0
        payment = (s["payment_status"] or "غير مدفوع") if "payment_status" in s.keys() else "—"

        rows += f"""<tr>
          <td>{s['product_name']}</td>
          <td>{s['license_type']}</td>
          <td>{s['device_count']}</td>
          <td>{s['start_date']}</td>
          <td>{s['end_date']}</td>
          <td><span class="badge">{display_status}</span></td>
          <td>{remaining_text}</td>
          <td>{price:.3f} ر.ع</td>
          <td>{payment}</td>
          <td style="direction:ltr;font-weight:bold">{s['license_key'] or '—'}</td>
        </tr>"""

    content = f"""
    <div class="customer-panel">
      <div class="admin-head">
        <div>
          <h1>حساب العميل</h1>
          <h2 style="margin-top:8px">مرحبًا {customer['name']} 👋</h2>
          <p>{customer['email']} &nbsp; | &nbsp; {customer['phone'] or 'بدون رقم هاتف'}</p>
        </div>
        <a class="btn btn-gold" href="/logout">تسجيل الخروج</a>
      </div>

      <div class="cards">
        <div class="stat"><span>إجمالي الأنظمة</span><b>{len(subs)}</b></div>
        <div class="stat"><span>الاشتراكات النشطة</span><b>{active}</b></div>
        <div class="stat"><span>قريبة الانتهاء</span><b>{expiring}</b></div>
        <div class="stat"><span>المنتهية</span><b>{expired}</b></div>
      </div>

      <div class="table-box">
        <h2>أنظمتي واشتراكاتي</h2>
        <p>يمكنك من هنا متابعة الترخيص، عدد الأجهزة، حالة الدفع وموعد انتهاء الاشتراك.</p>
        <table>
          <tr>
            <th>النظام</th><th>نوع الاشتراك</th><th>الأجهزة</th><th>البداية</th>
            <th>الانتهاء</th><th>الحالة</th><th>المتبقي</th><th>القيمة</th>
            <th>الدفع</th><th>رقم الترخيص</th>
          </tr>
          {rows or '<tr><td colspan="10">لا توجد اشتراكات مسجلة في حسابك حاليًا.</td></tr>'}
        </table>
      </div>

      <div class="form-box" style="max-width:none;margin-top:25px">
        <h2>تحتاج مساعدة أو تجديد؟</h2>
        <p>يمكنك إرسال طلب جديد من الموقع، وسيظهر مباشرة لدى إدارة سهيم نت.</p>
        <a class="btn btn-green" href="/custom">إرسال طلب</a>
      </div>
    </div>"""
    return page("بوابة العميل", content)


