@app.route("/admin/subscriptions", methods=["GET","POST"])
@admin_required
def admin_subscriptions():
    msg = ""
    today = datetime.now().date()

    with get_db() as con:
        customers = con.execute("SELECT id,name,email FROM customers WHERE status='نشط' ORDER BY name").fetchall()
        products = con.execute("SELECT id,name,annual_price FROM products ORDER BY name").fetchall()

    if request.method == "POST":
        action = request.form.get("action", "create")

        if action == "create":
            try:
                cid = int(request.form["customer_id"])
                pid = int(request.form["product_id"])
                start_date = datetime.strptime(request.form["start_date"], "%Y-%m-%d").date()
                license_type = request.form.get("license_type", "سنوي")
                devices = max(1, int(request.form.get("device_count") or 1))
                price = max(0.0, float(request.form.get("price") or 0))
                payment_status = request.form.get("payment_status", "غير مدفوع")

                if license_type == "سنوي":
                    try:
                        end_date = start_date.replace(year=start_date.year + 1)
                    except ValueError:
                        end_date = start_date.replace(year=start_date.year + 1, day=28)
                else:
                    raw_end = request.form.get("end_date", "").strip()
                    if not raw_end:
                        raise ValueError("أدخل تاريخ انتهاء الاشتراك المخصص.")
                    end_date = datetime.strptime(raw_end, "%Y-%m-%d").date()

                key = "SN-" + secrets.token_hex(3).upper() + "-" + secrets.token_hex(3).upper()

                with get_db() as con:
                    con.execute("""INSERT INTO subscriptions
                    (customer_id,product_id,license_type,device_count,start_date,end_date,status,license_key,price,payment_status)
                    VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    (cid,pid,license_type,devices,start_date.isoformat(),end_date.isoformat(),
                     "نشط",key,price,payment_status))
                msg = f'<div class="notice">تم إنشاء الاشتراك والترخيص بنجاح ✓ &nbsp; رقم الترخيص: <b>{key}</b></div>'
            except Exception as e:
                msg = f'<div class="notice" style="background:#fdecec;color:#a52a2a">تعذر إنشاء الاشتراك: {e}</div>'

        elif action == "status":
            sid = int(request.form["subscription_id"])
            new_status = request.form.get("status", "نشط")
            if new_status in ["نشط","موقوف","ملغي"]:
                with get_db() as con:
                    con.execute("UPDATE subscriptions SET status=? WHERE id=?", (new_status,sid))
                msg = '<div class="notice">تم تحديث حالة الاشتراك ✓</div>'

        elif action == "payment":
            sid = int(request.form["subscription_id"])
            pay = request.form.get("payment_status","غير مدفوع")
            if pay in ["مدفوع","غير مدفوع","مدفوع جزئياً"]:
                with get_db() as con:
                    con.execute("UPDATE subscriptions SET payment_status=? WHERE id=?", (pay,sid))
                msg = '<div class="notice">تم تحديث حالة الدفع ✓</div>'

    with get_db() as con:
        rows = con.execute("""SELECT s.*,c.name customer_name,c.email customer_email,p.name product_name
        FROM subscriptions s
        JOIN customers c ON c.id=s.customer_id
        JOIN products p ON p.id=s.product_id
        ORDER BY s.id DESC""").fetchall()

    customer_opts = "".join(f"<option value='{c['id']}'>{c['name']} — {c['email']}</option>" for c in customers)
    product_opts = "".join(f"<option value='{p['id']}'>{p['name']}</option>" for p in products)

    table_rows = []
    active = expiring = expired = 0
    for r in rows:
        try:
            end = datetime.strptime(r["end_date"], "%Y-%m-%d").date()
            days = (end - today).days
        except Exception:
            days = 9999

        stored_status = r["status"] or "نشط"
        if stored_status in ("موقوف","ملغي"):
            display_status = stored_status
        elif days < 0:
            display_status = "منتهي"
            expired += 1
        elif days <= 30:
            display_status = f"قريب الانتهاء ({days} يوم)"
            expiring += 1
        else:
            display_status = "نشط"
            active += 1

        table_rows.append(f"""<tr>
          <td>{r['customer_name']}</td><td>{r['product_name']}</td>
          <td>{r['license_type']}</td><td>{r['device_count']}</td>
          <td>{r['start_date']}</td><td>{r['end_date']}</td>
          <td><span class="badge">{display_status}</span></td>
          <td>{float(r['price'] or 0):.3f} ر.ع</td><td>{r['payment_status'] or 'غير مدفوع'}</td>
          <td style="direction:ltr">{r['license_key'] or '—'}</td>
          <td>
            <form method="POST" style="display:flex;gap:5px;flex-wrap:wrap">
              <input type="hidden" name="action" value="status">
              <input type="hidden" name="subscription_id" value="{r['id']}">
              <select name="status" style="min-width:100px">
                <option {'selected' if stored_status=='نشط' else ''}>نشط</option>
                <option {'selected' if stored_status=='موقوف' else ''}>موقوف</option>
                <option {'selected' if stored_status=='ملغي' else ''}>ملغي</option>
              </select><button class="small-btn">حفظ</button>
            </form>
          </td>
        </tr>""")

    tr = "".join(table_rows)
    content = f"""<div class="admin-wrap">
      <h1>الاشتراكات والتراخيص</h1>{admin_menu()}{msg}

      <div class="cards">
        <div class="stat"><span>إجمالي الاشتراكات</span><b>{len(rows)}</b></div>
        <div class="stat"><span>الاشتراكات النشطة</span><b>{active}</b></div>
        <div class="stat"><span>تنتهي خلال 30 يوماً</span><b>{expiring}</b></div>
        <div class="stat"><span>الاشتراكات المنتهية</span><b>{expired}</b></div>
      </div>

      <div class="form-box" style="max-width:none">
        <h2>إنشاء اشتراك وترخيص جديد</h2>
        <form method="POST"><div class="form-grid">
          <input type="hidden" name="action" value="create">
          <select name="customer_id" required><option value="">اختر العميل</option>{customer_opts}</select>
          <select name="product_id" required><option value="">اختر النظام</option>{product_opts}</select>
          <select name="license_type" required>
            <option value="سنوي">اشتراك سنوي</option>
            <option value="مخصص">مدة مخصصة</option>
          </select>
          <input type="number" name="device_count" min="1" value="1" placeholder="عدد الأجهزة" required>
          <label>تاريخ البداية<input type="date" name="start_date" value="{today.isoformat()}" required></label>
          <label>تاريخ الانتهاء للمدة المخصصة فقط<input type="date" name="end_date"></label>
          <input type="number" name="price" min="0" step="0.001" placeholder="قيمة الاشتراك بالريال العُماني">
          <select name="payment_status">
            <option>غير مدفوع</option><option>مدفوع</option><option>مدفوع جزئياً</option>
          </select>
          <button class="btn btn-green full">إنشاء الاشتراك وإصدار الترخيص</button>
        </div></form>
        <p style="margin-top:12px">ملاحظة: عند اختيار «اشتراك سنوي» يحسب النظام تاريخ الانتهاء تلقائياً بعد سنة.</p>
      </div><br>

      <div class="table-box"><table>
        <tr><th>العميل</th><th>النظام</th><th>النوع</th><th>الأجهزة</th><th>البداية</th>
        <th>الانتهاء</th><th>الحالة</th><th>القيمة</th><th>الدفع</th><th>رقم الترخيص</th><th>إدارة</th></tr>
        {tr or '<tr><td colspan="11">لا توجد اشتراكات حتى الآن.</td></tr>'}
      </table></div>
    </div>"""
    return page("الاشتراكات والتراخيص", content)




@app.route("/robots.txt")
def robots_txt():
    body = """User-agent: *
Allow: /
Disallow: /admin
Disallow: /customer
Disallow: /forgot
Disallow: /reset
Sitemap: https://saheemnet.com/sitemap.xml
"""
    return Response(body, mimetype="text/plain")

@app.route("/sitemap.xml")
def sitemap_xml():
    urls = ["/", "/products", "/pricing", "/custom", "/about", "/contact"]
    items = "".join(f"<url><loc>{SITE_URL}{u}</loc></url>" for u in urls)
    xml = f"""<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">{items}</urlset>"""
    return Response(xml, mimetype="application/xml")

@app.route("/asset/<path:filename>")
def assets(filename):
    # الشعار المفرغ مدمج داخل الملف لضمان ظهوره بدون خلفية سوداء
    if filename == "logo.png":
        return send_file(io.BytesIO(SAHEEM_LOGO_PNG), mimetype="image/png", max_age=86400)
    return send_from_directory(os.path.join(BASE_DIR, "asset"), filename)


